import {pageHeader,backButton,disclosure} from '../primitives.js?v=75';

const probabilityList = (title, rows) => `<section class="faq-probability-group"><h3>${title}</h3><dl class="probability-list">${rows.map(([label,value])=>`<div><dt>${label}</dt><dd>${value}%</dd></div>`).join('')}</dl></section>`;
const chestProbabilities = () => `<div class="chest-probabilities">${probabilityList('Что выпадает',[['Одна фигура',85],['Одна доска',10],['15 осколков',5]])}${probabilityList('Редкость предмета',[['Обычный',60],['Редкий',30],['Эпический',9],['Легендарный',1]])}<section class="faq-guarantee"><h3>Гарантия</h3><p>Десятое открытие без эпического или легендарного предмета гарантирует одну из этих редкостей.</p>${probabilityList('Редкость на гарантии',[['Эпический',90],['Легендарный',10]])}${probabilityList('Тип предмета на гарантии',[['Фигура',90],['Доска',10]])}<p>Повторы возможны и компенсируются осколками.</p></section></div>`;

export const faqPage = () => `<section id="faq" class="tab" data-page-kind="subpage" hidden>${pageHeader({title:"Вопросы и ответы",startContent:backButton('profile')})}<div class="page-content">${disclosure("Как начисляются монеты?","<article class=\"panel\"><p>За завершение партии — 5 монет. Дополнительно за победу — 18, ничью — 10, поражение — 5. Качество решений даёт ещё до 10 монет: точность — до 5, стабильность — до 3, лучшие решения — до 2.</p><p>Базовая награда начисляется сразу. Stockfish оценивает ходы на устройстве, в том числе без интернета; бонус начисляется после анализа. Можно продолжить пользоваться приложением. Если закрыть его, незаконченный расчёт возобновится при следующем запуске. При сбое расчёт повторится — до трёх попыток для проблемной позиции. Если оценку получить не удастся, дополнительно начислим резервный бонус в 5 монет. Базовая награда сохранится.</p><p>Важны доли хороших решений и ошибок, а не количество ходов. Единственный легальный ход не учитывается в качестве. Длинная партия сама по себе не приносит больше монет. Короткий мат и естественная ничья оплачиваются полностью.</p><p>Итого: победа — 23–33 монеты, ничья — 15–25, поражение — 10–20. Повторный просмотр не даёт новой награды. Сундук стоит 100 монет и открывается только по вашему нажатию; накопление 100 монет не запускает покупку автоматически.</p></article>")}${disclosure("Что выпадает из сундука?","<article class=\"panel\">"+chestProbabilities()+"</article>")}${disclosure("Для чего нужны осколки?","<article class=\"compensation panel\"><div><p>Монеты нужны для сундуков. Осколки — для создания конкретных фигур и досок. Обменять осколки обратно на монеты нельзя.</p><button class=\"quiet\" data-go=\"collection\">Открыть коллекцию</button></div><div class=\"table-scroll\"><table><caption>Осколки за повтор / стоимость создания</caption><thead><tr><th>Редкость</th><th>Фигура</th><th>Доска</th></tr></thead><tbody><tr><td>Обычная</td><td>8 / 40</td><td>16 / 80</td></tr><tr><td class=\"rare\">Редкая</td><td>20 / 100</td><td>40 / 200</td></tr><tr><td class=\"epic\">Эпическая</td><td>60 / 300</td><td>120 / 600</td></tr><tr><td class=\"legendary\">Легендарная</td><td>150 / 750</td><td>300 / 1500</td></tr></tbody></table></div></article>")}${disclosure("Что означают очки?","<article class=\"panel\"><p>Очки показывают разницу в материале на доске. Пешка — 1, конь и слон — 3, ладья — 5, ферзь — 9. Это не рейтинг и не валюта.</p></article>")}${disclosure("Как подбирается соперник?","<p>ИИ подстраивается под результаты ваших партий и может немного менять силу от игры к игре. Это внутренняя система GachaChess, а не официальный Elo.</p><p><a href=\"./engine-info.html\" target=\"_blank\" rel=\"noopener\">Как устроен ИИ</a></p>")}${disclosure("Когда можно сдаться?","<article class=\"panel\"><p>Сдача до первого вашего хода отменяет партию. После первого хода она считается поражением. Если сдаться до 10 собственных ходов, монеты и бонус за качество не начисляются. Начиная с 10-го собственного хода действует обычная награда за поражение. Незавершённые партии и партии, отменённые из-за ошибки ИИ, награду не дают.</p></article>")}${disclosure("Как работает календарь активности?","<article class=\"panel\"><p>Первую завершённую партию за день календарь отмечает как закрытый день. Результат и следующие партии этого дня на отметку не влияют. Последовательные дни образуют серию, но отдельных наград за неё нет.</p></article>")}</div></section>`;
